# radix edges carry strings; insertion splits edges at divergence
root = {}  # edge_label -> subtree; '$' marks word end

def insert(word):
    node = root
    while word:
        for edge in list(node):
            if edge == '$':
                continue
            i = 0
            while i < len(edge) and i < len(word) and edge[i] == word[i]:
                i += 1
            if i:
                child = node.pop(edge)
                mid = {}
                if i < len(edge):
                    mid[edge[i:]] = child
                if i < len(word):
                    mid[word[i:]] = {'$': True}
                else:
                    mid['$'] = True
                node[edge[:i]] = mid
                return
        node[word] = {'$': True}
        return

