def suggest(prefix, k=3):
    node = trie
    for ch in prefix:
        node = node.get(ch)
        if node is None:
            return []
    out = []
    def dfs(n, path):
        if '$' in n:
            out.append((n['$'], path))
        for ch, kid in sorted(n.items()):
            if ch != '$':
                dfs(kid, path + ch)
    dfs(node, prefix)
    return [w for _, w in sorted(out, reverse=True)[:k]]

