def fuzzy(node, query, i, edits, k, path, out):
    if edits > k:
        return
    if i == len(query):
        # collect completions below with remaining budget
        def dfs(n, p):
            if '$' in n:
                out.add((edits, n['$']))
            for ch, kid in n.items():
                if ch != '$':
                    dfs(kid, p + ch)
        dfs(node, path)
        return
    for ch, kid in node.items():
        if ch == '$':
            continue
        fuzzy(kid, query, i + 1, edits + (ch != query[i]), k, path + ch, out)
        fuzzy(kid, query, i, edits + 1, k, path + ch, out)  # insertion

