base = {'vector', 'version'}       # frozen FST (set stands in)
delta, tombstones = set(), set()       # mutable layer

def add(w):
    delta.add(w); tombstones.discard(w)

def remove(w):
    tombstones.add(w); delta.discard(w)

def lookup(prefix):
    cands = {w for w in base | delta if w.startswith(prefix)}
    return sorted(cands - tombstones)

