import random

trie = {}
words = set()

def insert(w):
    words.add(w)
    node = trie
    for ch in w:
        node = node.setdefault(ch, {})
    node['$'] = True

def complete(p):
    node = trie
    for ch in p:
        node = node.get(ch)
        if node is None:
            return []
    out = []
    def dfs(n, path):
        if '$' in n:
            out.append(path)
        for ch, k in n.items():
            if ch != '$':
                dfs(k, path + ch)
    dfs(node, p)
    return out

random.seed(3)
for _ in range(200):
    insert(''.join(random.choice('abc') for _ in range(random.randint(1, 6))))
# property: every completion starts with the prefix; every word is completable
for _ in range(100):
    w = random.choice(sorted(words))
    p = w[:random.randint(1, len(w))]
    res = complete(p)
    assert all(r.startswith(p) for r in res), 'prefix invariant'
    assert w in res, 'round-trip'
print('200 random words: prefix invariant + round-trip hold on 100 sampled prefixes')
